<div class="mt-6 flex gap-3"><label class="flex-1 flex items-center gap-3 bg-white border border-slate-200 rounded-xl px-4 h-14"><i data-lucide="search" class="w-5 h-5 text-slate-400 shrink-0"></i><input id="serviceSearch" class="w-full outline-none text-sm placeholder:text-slate-400" placeholder="Un service, un talent, un coup de main..." aria-label="Rechercher un service"></label><button id="filterToggle" type="button" aria-expanded="false" aria-controls="filterPanel" class="px-5 rounded-xl border border-slate-200 bg-white hover:border-teal-300 flex items-center gap-2 text-sm"><i data-lucide="sliders-horizontal" class="w-4 h-4"></i>Filtres</button></div>
<section id="filterPanel" class="hidden mt-3 p-5 md:p-6 bg-white border border-slate-200 rounded-xl" aria-label="Filtres de recherche"><div class="grid md:grid-cols-[1fr_1fr_auto] gap-6 items-end"><label class="text-sm text-slate-500">Budget maximum : <strong><span id="budgetValue">50</span> €</strong><input id="budgetFilter" type="range" min="5" max="50" value="50" class="mt-4 w-full accent-teal-600"></label><label class="text-sm text-slate-500">Trier par<select id="sortFilter" class="block mt-2 w-full rounded-lg border border-slate-200 px-3 py-2.5 text-slate-600 bg-white"><option value="recommended">Recommandés</option><option value="price-asc">Prix croissant</option><option value="rating-desc">Meilleures notes</option></select></label><button id="resetFilters" class="text-sm text-teal-700 hover:underline pb-2">Réinitialiser</button></div></section>
<div id="categories" class="grid grid-cols-4 lg:grid-cols-7 gap-2 md:gap-4 mt-6">
 <button data-category="all" class="category-button active-category rounded-2xl p-3 md:p-4 min-h-[100px] flex flex-col items-center justify-center gap-2 text-xs text-teal-700"><i data-lucide="layout-grid" class="w-6 h-6"></i><span>Tous les<br class="md:hidden"> services</span></button>
 <button data-category="coiffure" class="category-button rounded-2xl p-3 md:p-4 min-h-[100px] flex flex-col items-center justify-center gap-2 text-xs text-slate-500"><i data-lucide="scissors" class="w-6 h-6"></i><span>Coiffure<br>& beauté</span></button>
 <button data-category="cours" class="category-button rounded-2xl p-3 md:p-4 min-h-[100px] flex flex-col items-center justify-center gap-2 text-xs text-slate-500"><i data-lucide="book-open" class="w-6 h-6"></i><span>Cours<br>& soutien</span></button>
 <button data-category="demenagement" class="category-button rounded-2xl p-3 md:p-4 min-h-[100px] flex flex-col items-center justify-center gap-2 text-xs text-slate-500"><i data-lucide="package" class="w-6 h-6"></i><span>Déménagement</span></button>
 <button data-category="informatique" class="category-button rounded-2xl p-3 md:p-4 min-h-[100px] flex flex-col items-center justify-center gap-2 text-xs text-slate-500"><i data-lucide="monitor" class="w-6 h-6"></i><span>Informatique</span></button>
 <button data-category="photo" class="category-button rounded-2xl p-3 md:p-4 min-h-[100px] flex flex-col items-center justify-center gap-2 text-xs text-slate-500"><i data-lucide="camera" class="w-6 h-6"></i><span>Photo<br>& créa</span></button>
 <button data-category="autres" class="category-button rounded-2xl p-3 md:p-4 min-h-[100px] flex flex-col items-center justify-center gap-2 text-xs text-slate-500"><i data-lucide="sparkles" class="w-6 h-6"></i><span>Autres</span></button>
</div>
<script>
document.addEventListener('DOMContentLoaded',()=>{const toggle=document.getElementById('filterToggle');if(!toggle)return;const panel=document.getElementById('filterPanel'),search=document.getElementById('serviceSearch'),budget=document.getElementById('budgetFilter'),budgetValue=document.getElementById('budgetValue'),sort=document.getElementById('sortFilter'),cards=[...document.querySelectorAll('.service-card')];let category='all';toggle.addEventListener('click',()=>{const opening=panel.classList.contains('hidden');panel.classList.toggle('hidden');toggle.setAttribute('aria-expanded',String(opening))});function update(){const query=search.value.trim().toLocaleLowerCase('fr'),limit=Number(budget.value);budgetValue.textContent=limit;let shown=cards.filter(card=>(category==='all'||card.dataset.category===category)&&Number(card.dataset.price)<=limit&&card.dataset.title.includes(query));if(sort.value==='price-asc')shown.sort((a,b)=>Number(a.dataset.price)-Number(b.dataset.price));if(sort.value==='rating-desc')shown.sort((a,b)=>Number(b.dataset.rating)-Number(a.dataset.rating));const grid=document.querySelector('.service-grid'),empty=document.getElementById('emptyResults');if(grid&&empty)shown.forEach(card=>grid.insertBefore(card,empty));cards.forEach(card=>card.classList.toggle('hidden',!shown.includes(card)));if(empty)empty.classList.toggle('hidden',shown.length!==0)}search.addEventListener('input',update);budget.addEventListener('input',update);sort.addEventListener('change',update);document.querySelectorAll('.category-button').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.category;document.querySelectorAll('.category-button').forEach(item=>item.classList.toggle('active-category',item===button));update()}));document.getElementById('resetFilters').addEventListener('click',()=>{search.value='';budget.value='50';sort.value='recommended';category='all';document.querySelectorAll('.category-button').forEach(button=>button.classList.toggle('active-category',button.dataset.category==='all'));update()});document.querySelectorAll('.favorite-button').forEach(button=>button.addEventListener('click',()=>{button.classList.toggle('text-rose-500');button.setAttribute('aria-pressed',String(button.classList.contains('text-rose-500')))}))});
</script>
